mapper.select:
SELECT b.*, s.name AS store_name, u.username AS creator_name, TIMESTAMPDIFF(MINUTE, b.entry_time, b.leave_time) AS stay_duration_minutes, (SELECT GROUP_CONCAT(DISTINCT z.name ORDER BY zs.entry_time SEPARATOR ', ') FROM t_zone_stay zs LEFT JOIN t_zone z ON zs.zone_id = z.id WHERE zs.behavior_id = b.id) AS zone_names FROM t_customer_behavior b LEFT JOIN t_store s ON b.store_id = s.id LEFT JOIN t_user u ON b.created_by = u.id
b.status = 1
AND b.store_id = #{params.storeId}
AND b.store_id IN #{id}
AND b.is_purchased = #{params.isPurchased}
AND b.entry_time >= #{params.startDate}
AND b.entry_time <= #{params.endDate}
AND s.name LIKE CONCAT('%', #{params.keyword}, '%')
ORDER BY b.entry_time DESC

SELECT DATE_FORMAT(entry_time, '%Y-%m-%d %H:00') AS time_key, HOUR(entry_time) AS hour, COUNT(*) AS total_count, SUM(CASE WHEN is_purchased = 1 THEN 1 ELSE 0 END) AS purchase_count FROM t_customer_behavior WHERE status = 1
AND store_id = #{storeId}
AND store_id IN #{id}
AND entry_time >= #{startDate}
AND entry_time <= #{endDate}
GROUP BY time_key, hour ORDER BY time_key

SELECT DATE_FORMAT(entry_time, '%Y-%m-%d') AS date_key, COUNT(*) AS total_count, SUM(CASE WHEN is_purchased = 1 THEN 1 ELSE 0 END) AS purchase_count, ROUND(AVG(TIMESTAMPDIFF(MINUTE, entry_time, leave_time)), 1) AS avg_duration_min FROM t_customer_behavior WHERE status = 1
AND store_id = #{storeId}
AND store_id IN #{id}
AND entry_time >= #{startDate}
AND entry_time <= #{endDate}
GROUP BY date_key ORDER BY date_key

SELECT z.id AS zone_id, z.name AS zone_name, z.pos_x, z.pos_y, z.width, z.height, COUNT(DISTINCT zs.behavior_id) AS visitor_count, ROUND(AVG(TIMESTAMPDIFF(MINUTE, zs.entry_time, zs.leave_time)), 1) AS avg_stay_min, SUM(TIMESTAMPDIFF(MINUTE, zs.entry_time, zs.leave_time)) AS total_stay_min FROM t_zone_stay zs JOIN t_zone z ON zs.zone_id = z.id JOIN t_customer_behavior b ON zs.behavior_id = b.id WHERE b.status = 1 AND z.status = 1
AND z.store_id = #{storeId}
AND z.store_id IN #{id}
AND b.entry_time >= #{startDate}
AND b.entry_time <= #{endDate}
GROUP BY z.id, z.name, z.pos_x, z.pos_y, z.width, z.height ORDER BY visitor_count DESC

SELECT COUNT(*) AS total_visitors, SUM(CASE WHEN is_purchased = 1 THEN 1 ELSE 0 END) AS purchase_count, ROUND(SUM(CASE WHEN is_purchased = 1 THEN 1 ELSE 0 END) * 100.0 / COUNT(*), 2) AS conversion_rate, ROUND(AVG(TIMESTAMPDIFF(MINUTE, entry_time, leave_time)), 1) AS avg_duration_min, ROUND(AVG(CASE WHEN is_purchased = 1 THEN TIMESTAMPDIFF(MINUTE, entry_time, leave_time) ELSE NULL END), 1) AS avg_purchase_duration_min, ROUND(AVG(CASE WHEN is_purchased = 0 THEN TIMESTAMPDIFF(MINUTE, entry_time, leave_time) ELSE NULL END), 1) AS avg_no_purchase_duration_min FROM t_customer_behavior WHERE status = 1
AND store_id = #{storeId}
AND store_id IN #{id}
AND entry_time >= #{startDate}
AND entry_time <= #{endDate}

SELECT
    (SELECT COUNT(*) FROM t_customer_behavior WHERE status = 1
     AND store_id = #{storeId}

         AND store_id IN #{id}

     AND DATE(entry_time) = CURDATE()) AS today_visitors,
    (SELECT COUNT(*) FROM t_customer_behavior WHERE status = 1 AND is_purchased = 1
     AND store_id = #{storeId}

         AND store_id IN #{id}

     AND DATE(entry_time) = CURDATE()) AS today_purchases,
    (SELECT COUNT(*) FROM t_customer_behavior WHERE status = 1
     AND store_id = #{storeId}

         AND store_id IN #{id}
     ) AS total_visitors,
    ROUND(
        (SELECT COUNT(*) FROM t_customer_behavior WHERE status = 1 AND is_purchased = 1
         AND store_id = #{storeId}

             AND store_id IN #{id}
         )
        * 100.0 / NULLIF((SELECT COUNT(*) FROM t_customer_behavior WHERE status = 1
         AND store_id = #{storeId}

             AND store_id IN #{id}
         ), 0)
    , 2) AS total_conversion_rate,
    ROUND(AVG(TIMESTAMPDIFF(MINUTE, entry_time, leave_time)), 1) AS avg_stay_duration
FROM t_customer_behavior
WHERE status = 1
AND store_id = #{storeId}

    AND store_id IN #{id}

SELECT s.id AS store_id, s.name AS store_name, COUNT(b.id) AS visitor_count, SUM(CASE WHEN b.is_purchased = 1 THEN 1 ELSE 0 END) AS purchase_count, ROUND(AVG(TIMESTAMPDIFF(MINUTE, b.entry_time, b.leave_time)), 1) AS avg_duration_min FROM t_store s LEFT JOIN t_customer_behavior b ON s.id = b.store_id AND b.status = 1
AND b.entry_time >= #{startDate}
AND b.entry_time <= #{endDate}
WHERE s.status = 1
AND s.id IN
#{id}
GROUP BY s.id, s.name ORDER BY visitor_count DESC
